// 标题栏实时化：真实时钟 + 值班人姓名（每 1 秒执行一次）
// 值班角色与姓名改下面两行，保存后画面 1 秒内生效。
var DUTY_ROLE = '值班员';   // 管理员 / 值班员 / 调度员 ...
var DUTY_NAME = '王工';     // 当前值班人姓名
var pad = function (n) { return (n < 10 ? '0' : '') + n; };
var d = new Date();
var clock = pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
var nodes = document.querySelectorAll('svg text');
for (var i = 0; i < nodes.length; i++) {
    var s = (nodes[i].textContent || '').trim();
    if (/^[0-9]{2}:[0-9]{2}:[0-9]{2}$/.test(s)) {
        nodes[i].textContent = clock;
    } else if (/^(管理员|值班员|调度员|操作员)[ ]*·/.test(s)) {
        nodes[i].textContent = DUTY_ROLE + ' · ' + DUTY_NAME;
    }
}

// 矿区「视频窗」实时流 —— 钉住 + 自愈（本脚本每秒被平台重跑，必须幂等）
//
// 为什么需要它（全部为实测结论，别删注释）：
//   1) 平台每次切换视图都会【重建】<image> 元素，href 退回 /api/cameras/.../snapshot，
//      也就是退回"抓拍模式"（约 1 帧/秒），并每秒打一次平台 API。
//      早期版本用 window.__scadiaTile.done 做"只换一次"的守卫，切一次视图后就永久失效
//      —— 实测：第 2 次进「AI 检测」时 4 个窗全部退回 snapshot，再也回不来。
//   2) 4 个窗每秒打 snapshot ≈ 48 次/分钟，会打爆平台 1000 次/5 分钟的全站配额 → 429 → 黑屏。
//   3) Chrome 对断掉的 MJPEG 流【永不自动重连】：SVG <image> 只触发一次 load，永不触发 error
//      （隔离实验：服务端主动关流后 8 秒内零重连）。所以 mjpeg-proxy 一重启，
//      已打开的页面就永久黑屏。⇒ href 必须每秒重新钉住，连接必须主动探测并按需重连。
//
// ★ v3 的关键改动：不再用 setInterval 做看门狗。
//   教训（本批真实踩到）：脚本可以热更新，但已经建好的 setInterval 里抓的是【旧函数】，
//   旧逻辑会一直跑到页面刷新为止 —— 现场表现就是"新文案出来了、新逻辑没跑"。
//   平台本来就每秒重跑一遍本脚本，所以直接把看门狗挂在这条心跳上（用时间戳节流），
//   就没有"定时器换不掉"这个失败模式了。
//
// 三段职责：
//   A. videoPin()    —— 每次心跳把每个视频窗的 href 钉在 MJPEG 地址上（含每窗唯一 id）
//   B. videoPoll()   —— 每 10 秒问代理 /stats：我这个窗的 id 还在线吗？不在就换地址重连
//   C. videoLabels() —— 顶栏文案按真实状态书写（含失败原因，便于现场一眼定位）
//
// 注意：不要用反引号（工程里插入 JS 的链路会截断模板字符串）。

var VIDEO_VER = 5;                       // 改脚本必须改这个号，老逻辑才会被作废
var VIDEO_HOST = location.protocol + "//" + location.hostname + ":1886";
var VIDEO_BASE = VIDEO_HOST + "/mjpeg/kuangqu1";
var VIDEO_STATS = VIDEO_HOST + "/stats";
var VIDEO_SOURCE = "kuangqu1";
var POLL_MS = 10000;                     // 看门狗间隔（靠心跳节流，不是定时器）
var REVIVE_COOLDOWN_MS = 15000;          // 同一个窗的重连冷却
var BLIND_REFRESH_MS = 1800000;          // 30 分钟兜底全刷一次

var _vst = (window.__scadiaVideo = window.__scadiaVideo || {});
if (_vst.ver !== VIDEO_VER) {
    if (_vst.timer) { clearInterval(_vst.timer); }     // 作废旧版本的定时器
    _vst.timer = null;
    _vst.ver = VIDEO_VER;
    _vst.rev = {};
    _vst.revAt = {};
    _vst.lastPoll = 0;
    _vst.lastBlind = 0;
    _vst.online = null;
    _vst.fps = 0;
    _vst.why = "启动";
    _vst.revives = 0;
    _vst.firstAt = 0;
}

function videoPanes() {
    var out = [], all = document.querySelectorAll("svg image");
    for (var i = 0; i < all.length; i++) {
        var h = all[i].getAttribute("href") || all[i].getAttribute("xlink:href") || "";
        if (h.indexOf("/mjpeg/") >= 0 || h.indexOf("/api/cameras/") === 0 || h.indexOf("blob:") === 0) { out.push(all[i]); }
    }
    return out;
}
function videoUrl(cid) {
    return VIDEO_BASE + "?c=" + cid + "&r=" + (_vst.rev[cid] || 0);
}
function videoRevive(cid, now) {
    _vst.rev[cid] = (_vst.rev[cid] || 0) + 1;
    _vst.revAt[cid] = now;
    _vst.revives++;
}
// A. 每次心跳钉住。值与期望不同才写，避免把正在跑的流反复重启。
function videoPin() {
    var panes = videoPanes();
    for (var i = 0; i < panes.length; i++) {
        var cid = "w" + (i + 1);
        var want = videoUrl(cid);
        var cur = panes[i].getAttribute("href") || "";
        if (cur !== want) {
            panes[i].setAttributeNS("http://www.w3.org/1999/xlink", "xlink:href", want);
            panes[i].setAttribute("href", want);
        }
    }
    return panes.length;
}
// B. 看门狗（由心跳驱动，不用定时器）
function videoPoll() {
    var now = new Date().getTime();
    var n = videoPanes().length;
    if (!n) { _vst.online = true; _vst.why = "本视图无视频窗"; return; }
    if (!_vst.lastBlind) { _vst.lastBlind = now; }
    var blind = (now - _vst.lastBlind) > BLIND_REFRESH_MS;
    fetch(VIDEO_STATS + "?t=" + now, { cache: "no-store" })
        .then(function (r) { return r.ok ? r.json() : null; })
        .then(function (j) {
            if (!j || !j.sources) { _vst.online = false; _vst.why = "代理不可达"; videoLabels(); return; }
            _vst.online = true;
            var src = j.sources[VIDEO_SOURCE];
            if (!src) {
                _vst.fps = 0; _vst.why = "代理无此源";
                // 刚钉上不久就"查无此源"，多半只是登记延迟，不要白重启一次流
                if (now - _vst.firstAt < 6000) { videoLabels(); return; }
                // 代理活着但这条源上一个人都没有 ⇒ 我们那些连接早就死了，全部重连
                for (var q = 1; q <= n; q++) { if (now - (_vst.revAt["w" + q] || 0) > REVIVE_COOLDOWN_MS) { videoRevive("w" + q, now); } }
                videoPin(); videoLabels();
                return;
            }
            _vst.fps = src.fps || 0;
            _vst.why = _vst.fps > 0 ? "正常" : "代理无帧";
            if (blind) { _vst.lastBlind = now; }
            var ids = src.clientIds || [];
            var revived = 0;
            for (var i = 0; i < n; i++) {
                var cid = "w" + (i + 1);
                // 我不在代理的在线名单里 = 这条连接死了；冷却期内不重复重连
                if (ids.indexOf(cid) < 0 && (now - (_vst.revAt[cid] || 0)) > REVIVE_COOLDOWN_MS) { videoRevive(cid, now); revived++; }
            }
            if (blind) { for (var k = 1; k <= n; k++) { videoRevive("w" + k, now); } revived++; }
            if (revived) { videoPin(); }
            videoLabels();
        })
        .catch(function () { _vst.online = false; _vst.why = "代理不可达"; videoLabels(); });
}
// C. 顶栏文案：按正则找、按真实状态写（文本会被平台重建，所以每次心跳都要写一遍）
function videoText(re, give) {
    var ts = document.querySelectorAll("svg text");
    for (var i = 0; i < ts.length; i++) {
        var s = (ts[i].textContent || "").trim();
        if (s !== give && re.test(s)) { ts[i].textContent = give; }
    }
}
// 顶栏第二个徽标是"AI 引擎"位：正常时保持原来那句 YOLOv8 + ByteTrack（用户认这个），
// 只有真的出问题时才换成诊断文案 —— 报错信息只在需要时出现，平时不占地方。
function videoLabelText() {
    if (_vst.why === "本视图无视频窗") { return "YOLOv8 + ByteTrack"; }
    if (_vst.online === false) { return "YOLOv8 · 视频代理不可达"; }
    if (_vst.online === null) { return "YOLOv8 · 视频探测中"; }
    if (_vst.fps >= 10) { return "YOLOv8 + ByteTrack"; }
    if (_vst.fps > 0) { return "YOLOv8 · 视频慢 " + _vst.fps + " 帧/秒"; }
    if (_vst.why === "代理无此源") { return "YOLOv8 · 视频重连中"; }
    return "YOLOv8 · 等待视频帧";
}
function videoLabels() {
    videoText(/^(AI 推理 待接入|AI 推理 在线|AI 推理 4 类 · 在线)$/, "AI 推理 在线");
    // 正则要宽松：老脚本可能已经把这一格写成 YOLOv8 + ByteTrack，必须能接管过来
    videoText(/^(抓拍约 1 帧\/秒|实时流 .*|YOLOv8.*)$/, videoLabelText());
}

// ---- 主循环：挂在平台每秒的心跳上，不建定时器 ----
// 回到前台时强制全量重连一次：浏览器把后台标签页的定时器/连接冻结过，
// 而用户恰恰是在切回来的那一刻发现"画面没了"。
if (!_vst.onVis) {
    _vst.onVis = function () {
        if (document.visibilityState !== "visible") { return; }
        _vst.lastPoll = 0;                       // 立刻重新探测一次
        if (_vst.fps > 0) { return; }            // 还在正常出帧就别折腾
        // 后台标签页被浏览器冻结过 —— 用户恰恰是在切回来的这一刻发现"画面没了"
        var now = new Date().getTime();
        var n = videoPanes().length;
        for (var k = 1; k <= n; k++) { videoRevive("w" + k, now); }
        videoPin();
    };
    document.addEventListener("visibilitychange", _vst.onVis);
}

var _now = new Date().getTime();
if (!_vst.firstAt) { _vst.firstAt = _now; }
videoPin();
videoLabels();
// 首次探测压到 6 秒之后：刚钉上的连接还没在代理那边登记，
// 立刻去问会被误判成"全断了"而白重启一次流。
var _grace = (_now - _vst.firstAt) < 6000;
if (!_grace && _now - (_vst.lastPoll || 0) >= POLL_MS) { _vst.lastPoll = _now; videoPoll(); }

// 在 4 个视频窗上画 AI 检测框、人体轨迹与电子围栏（全部读 /_images/ 静态文件，不走平台 API）。
// 坐标用窗元素自身的 x/y/width/height 做映射，落在同一个 viewBox 里，不受画面缩放影响。
//
// 两件要紧事：
//  1) 本脚本被平台**每秒重跑一次**，普通 var 每次都会重置；轨迹要跨次累积，
//     所以状态挂在 window.__aiTrail 上，并只在第一次启动 250ms 的采样定时器（否则每秒多一个定时器）。
//  2) 检测框来自外部 AI 引擎（scadia-ai-tracker.py，YOLOv8+ByteTrack），带**真实 bbox**；
//     早期版本因为相机原生事件不带坐标，只能画满幅框——那个已经被这里取代。
var CAM_ID = "cam_6b153dde0e03";
var LAYER = "ai_det_layer";
var TRAIL_LAYER = "ai_trail_layer";
var POLL_MS = 250;      // 采样间隔（平台每秒重跑，但内部定时器只建一次）
var TRAIL_MAX = 80;     // 每条轨迹最多保留的点数
var TRAIL_TTL = 3000;   // 超过这么久没再出现就丢弃该轨迹
var TRAIL_COLOR = "#ffd166";
var BOX_COLOR = "#ff5468";
var STALE_MS = 5000;    // 静态文件超过这么久没更新 => 引擎已停，按"无目标"处理（别让框赖着不走）
var FENCE_LAYER = "ai_fence_layer";
var FENCE_FILE = "/_images/ai-fence.json";   // 桥接器发布：围栏多边形 + 刚刚触发的状态

// ---- 电子围栏：把相机里的 FieldDetection 多边形画到每个视频窗上 ----
// 围栏坐标是 0..scale 的定点（与 /ISAPI/Smart/FieldDetection/1 一致），
// 映射方式和检测框一样：用窗元素自身的 x/y/width/height，落在同一个 viewBox 里。
function aiDrawFence(fence) {
    var panes = aiPanes();
    if (!panes.length) { return; }
    var svg = panes[0].ownerSVGElement;
    var layer = aiLayer(svg, FENCE_LAYER);
    while (layer.firstChild) { layer.removeChild(layer.firstChild); }
    if (!fence || !fence.points || fence.points.length < 3) { return; }

    var scale = fence.scale || 1000;
    var now = new Date().getTime();
    var hot = fence.activeKind === 'fielddetection' && fence.activeAt && (now - fence.activeAt) < (fence.highlightMs || 3000);
    var stroke = hot ? '#ff2d4b' : '#35e08a';
    var opacity = hot ? '1' : '0.75';
    var sw = hot ? '4' : '2.5';

    // 电子围栏只画在 CH-1（第一个窗 = 区域入侵窗）：四个窗都画太重，境界本来就是区域入侵的语义
    for (var p = 0; p < 1; p++) {
        var el = panes[p];
        var px = parseFloat(el.getAttribute("x")) || 0, py = parseFloat(el.getAttribute("y")) || 0;
        var pw = parseFloat(el.getAttribute("width")) || 0, ph = parseFloat(el.getAttribute("height")) || 0;
        var pts = [];
        for (var i = 0; i < fence.points.length; i++) {
            var nx = fence.points[i][0] / scale, ny = fence.points[i][1] / scale;
            pts.push((px + nx * pw).toFixed(1) + "," + (py + ny * ph).toFixed(1));
        }
        var poly = document.createElementNS("http://www.w3.org/2000/svg", "polygon");
        poly.setAttribute("points", pts.join(" "));
        poly.setAttribute("fill", hot ? "rgba(255,45,75,0.10)" : "none");
        poly.setAttribute("stroke", stroke);
        poly.setAttribute("stroke-width", sw);
        poly.setAttribute("stroke-opacity", opacity);
        poly.setAttribute("stroke-dasharray", "10 6");
        layer.appendChild(poly);
        // 四个角标：让围栏边界一眼可辨，不受虚线间隙影响
        for (var k = 0; k < fence.points.length; k++) {
            var q = pts[k].split(",");
            var c = document.createElementNS("http://www.w3.org/2000/svg", "rect");
            c.setAttribute("x", (parseFloat(q[0]) - 5).toFixed(1));
            c.setAttribute("y", (parseFloat(q[1]) - 5).toFixed(1));
            c.setAttribute("width", "10"); c.setAttribute("height", "10");
            c.setAttribute("fill", "none"); c.setAttribute("stroke", stroke); c.setAttribute("stroke-width", "2.5");
            layer.appendChild(c);
        }
        // 标签
        var t = document.createElementNS("http://www.w3.org/2000/svg", "text");
        t.setAttribute("x", (px + 10).toFixed(1)); t.setAttribute("y", (py + ph - 12).toFixed(1));
        t.setAttribute("font-size", "15"); t.setAttribute("font-family", "微软雅黑");
        t.setAttribute("fill", "#ffffff"); t.setAttribute("paint-order", "stroke");
        t.setAttribute("stroke", stroke); t.setAttribute("stroke-width", "3");
        t.textContent = (fence.label || '电子围栏') + (hot ? ' · 入侵中' : '');
        layer.appendChild(t);
    }
}

function aiToken() {
    try {
        for (var i = 0; i < localStorage.length; i++) {
            var v = localStorage.getItem(localStorage.key(i));
            if (v && v.charAt(0) === "{") { var o = JSON.parse(v); if (o && o.token) { return o.token; } }
            if (v && v.indexOf("eyJ") === 0) { return v; }
        }
    } catch (e) { }
    return null;
}
function aiPanes() {
    var out = [], all = document.querySelectorAll("svg image");
    for (var i = 0; i < all.length; i++) {
        var h = all[i].getAttribute("href") || all[i].getAttribute("xlink:href") || "";
        if (h.indexOf("/mjpeg/") >= 0 || h.indexOf("/api/cameras/") === 0 || h.indexOf("blob:") === 0) { out.push(all[i]); }
    }
    return out;
}
function aiLayer(svg, id) {
    var el = document.getElementById(id);
    if (!el) {
        el = document.createElementNS("http://www.w3.org/2000/svg", "g");
        el.setAttribute("id", id);
        el.setAttribute("pointer-events", "none");
        svg.appendChild(el);
    }
    return el;
}
function aiNormText(want, give) {
    // 把画面里写死的过时文案就地改掉（按文字找，不依赖坐标）
    var ts = document.querySelectorAll("svg text");
    for (var i = 0; i < ts.length; i++) {
        if (ts[i].textContent === want) { ts[i].textContent = give; }
    }
}
function aiDraw(dets) {
    var panes = aiPanes();
    if (!panes.length) { return; }
    var svg = panes[0].ownerSVGElement;
    var layer = aiLayer(svg, LAYER);
    var tl = aiLayer(svg, TRAIL_LAYER);
    while (layer.firstChild) { layer.removeChild(layer.firstChild); }
    while (tl.firstChild) { tl.removeChild(tl.firstChild); }
    if (!dets || !dets.length) { return; }
    var W = window.__aiTrail;
    var now = new Date().getTime();
    for (var p = 0; p < panes.length; p++) {
        var el = panes[p];
        var px = parseFloat(el.getAttribute("x")) || 0, py = parseFloat(el.getAttribute("y")) || 0;
        var pw = parseFloat(el.getAttribute("width")) || 0, ph = parseFloat(el.getAttribute("height")) || 0;
        for (var k = 0; k < dets.length; k++) {
            var r = dets[k].region;
            if (!r) { continue; }
            var x = px + r.x * pw, y = py + r.y * ph, w = r.w * pw, h = r.h * ph;
            var rect = document.createElementNS("http://www.w3.org/2000/svg", "rect");
            rect.setAttribute("x", x); rect.setAttribute("y", y); rect.setAttribute("width", w); rect.setAttribute("height", h);
            rect.setAttribute("fill", "none"); rect.setAttribute("stroke", BOX_COLOR); rect.setAttribute("stroke-width", "3");
            layer.appendChild(rect);
            var label = dets[k].label || "检测";
            var score = dets[k].score != null ? " " + Math.round(dets[k].score * 100) + "%" : "";
            var tid = dets[k].id ? " #" + dets[k].id : "";
            var tag = document.createElementNS("http://www.w3.org/2000/svg", "text");
            tag.setAttribute("x", x + 6); tag.setAttribute("y", y + 20);
            tag.setAttribute("font-size", "16"); tag.setAttribute("font-family", "微软雅黑");
            tag.setAttribute("fill", "#ffffff"); tag.setAttribute("paint-order", "stroke");
            tag.setAttribute("stroke", BOX_COLOR); tag.setAttribute("stroke-width", "3");
            tag.textContent = label + tid + score;
            layer.appendChild(tag);

            // ---- 轨迹：把该 trackId 的历史中心点连成折线 ----
            var tr = W.trails[dets[k].id];
            if (tr && tr.pts && tr.pts.length > 1) {
                var pts = [];
                for (var q = 0; q < tr.pts.length; q++) {
                    pts.push((px + tr.pts[q].x * pw).toFixed(1) + "," + (py + tr.pts[q].y * ph).toFixed(1));
                }
                var pl = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
                pl.setAttribute("points", pts.join(" "));
                pl.setAttribute("fill", "none");
                pl.setAttribute("stroke", TRAIL_COLOR);
                pl.setAttribute("stroke-width", "2.5");
                pl.setAttribute("stroke-opacity", "0.85");
                pl.setAttribute("stroke-linejoin", "round");
                pl.setAttribute("stroke-linecap", "round");
                tl.appendChild(pl);
                // 头部圆点 + 起点方块
                var head = tr.pts[tr.pts.length - 1], tail = tr.pts[0];
                var c1 = document.createElementNS("http://www.w3.org/2000/svg", "circle");
                c1.setAttribute("cx", px + head.x * pw); c1.setAttribute("cy", py + head.y * ph);
                c1.setAttribute("r", "5"); c1.setAttribute("fill", TRAIL_COLOR);
                tl.appendChild(c1);
                var c2 = document.createElementNS("http://www.w3.org/2000/svg", "circle");
                c2.setAttribute("cx", px + tail.x * pw); c2.setAttribute("cy", py + tail.y * ph);
                c2.setAttribute("r", "4"); c2.setAttribute("fill", "none");
                c2.setAttribute("stroke", TRAIL_COLOR); c2.setAttribute("stroke-width", "2");
                tl.appendChild(c2);
            }
        }
    }
    // 顶栏文案的纠正已移交给 s_camera_live（这里被 aiDraw 的两个 early-return 挡死，永远走不到）
}
function aiRemember(dets) {
    var W = window.__aiTrail, now = new Date().getTime();
    if (dets && dets.length) {
        for (var k = 0; k < dets.length; k++) {
            var d = dets[k];
            if (!d || !d.region || !d.id) { continue; }
            var t = W.trails[d.id];
            if (!t) { t = W.trails[d.id] = { pts: [] }; }
            t.at = now;
            var cx = d.region.x + d.region.w / 2, cy = d.region.y + d.region.h / 2;
            var last = t.pts[t.pts.length - 1];
            // 位移太小就不记点，避免站着不动也堆一串重合点
            if (!last || Math.abs(last.x - cx) > 0.002 || Math.abs(last.y - cy) > 0.002) {
                t.pts.push({ x: cx, y: cy });
                if (t.pts.length > TRAIL_MAX) { t.pts.shift(); }
            }
        }
    }
    for (var id in W.trails) {
        if (W.trails.hasOwnProperty(id) && now - W.trails[id].at > TRAIL_TTL) { delete W.trails[id]; }
    }
}
