function aiOpsToken() {
    // 平台真实登录后 token 存在 sessionStorage.currentUser（不是 localStorage）。
    // 只扫 localStorage 时真实用户永远拿不到 token，清零必然 401 —— 实测坐实。
    try {
        var cu = sessionStorage.getItem("currentUser");
        if (cu) { var so = JSON.parse(cu); if (so && so.token) { return so.token; } }
    } catch (e) { }
    try {
        for (var i = 0; i < localStorage.length; i++) {
            var v = localStorage.getItem(localStorage.key(i));
            if (v && v.charAt(0) === "{") { var o = JSON.parse(v); if (o && o.token) { return o.token; } }
            if (v && v.indexOf("eyJ") === 0) { return v; }
        }
    } catch (e) { }
    return null;
}

