];
var DB_ALIAS = { tamperdetection: 'tamper', motiondetection: 'VMD', vmd: 'VMD' };

function dbTexts() { return document.querySelectorAll('svg text'); }

function dbSetAll(pred, fn) {
  var ts = dbTexts(), n = 0;
  for (var i = 0; i < ts.length; i++) {
    var cur = (ts[i].textContent || '').trim();
    if (pred(cur)) {
      var next = fn(cur, n);
      if (next != null && ts[i].textContent !== next) { ts[i].textContent = next; }
      n++;
    }
  }
  return n;
}

function dbByKind() {
  return fetch('/_images/ai-counts.json?t=' + Date.now())
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (j) {
      var raw = (j && j.byKind) || {}, out = {};
      for (var k in raw) { if (raw.hasOwnProperty(k)) { out[DB_ALIAS[k] || k] = raw[k]; } }
      return out;
    })
    .catch(function () { return {}; });
}

function dbApply(by) {
  var n0 = by['fielddetection'] || 0, n1 = by['tamper'] || 0, n2 = by['VMD'] || 0, n3 = by['videoloss'] || 0;
  var all = n0 + n1 + n2 + n3;

  // 1) 三块"共计 N 次" —— 依次换成 区域入侵 / 遮挡 / 移动侦测 的真实次数
  var seq = [n0, n1, n2];
  dbSetAll(function (t) { return /^共计\s+\d+\s+次$/.test(t); }, function (t, i) {
    var v = seq[i] != null ? seq[i] : all;
    return '共计     ' + v + '    次';
  });

  // 2) 三块统计标题：矿业务语汇 -> 实际在检测的四类
  dbSetAll(function (t) { return t === '全矿异物报警统计'; }, function () { return '区域入侵统计'; });
  dbSetAll(function (t) { return t === '全矿跑偏报警统计'; }, function () { return '遮挡报警统计'; });
  dbSetAll(function (t) { return t === '全矿堆煤报警统计'; }, function () { return '移动侦测统计'; });

  // 3) 那一列 8 个"分类1" -> 真实类别名（循环填）
  var names = ['区域入侵', '遮挡报警', '移动侦测', '视频丢失', '人员轨迹', '视频丢失', '遮挡报警', '移动侦测'];
  dbSetAll(function (t) { return t === '分类1'; }, function (t, i) { return names[i % names.length]; });

  // 4) 趋势图标题里的写死日期 -> 真实区间（近 7 日）
  var d2 = new Date(), d1 = new Date(Date.now() - 6 * 86400000);
  var fmt = function (d) { return d.getFullYear() + '.' + ('0' + (d.getMonth() + 1)).slice(-2) + '.' + ('0' + d.getDate()).slice(-2); };
  dbSetAll(function (t) { return /^趋势图（\d{4}\.\d{2}-\d{4}\.\d{2}）$/.test(t); },
    function () { return '趋势图（' + fmt(d1) + '-' + fmt(d2) + '）'; });

  // 5) 两个写死的百分比 -> 用真实占比（有数据才算）
  var p0 = all > 0 ? Math.round(n0 * 100 / all) : 0;
  dbSetAll(function (t) { return t === '占比20%'; }, function () { return '占比' + p0 + '%'; });

  // 6) 顶部"AI 推理 4 路 · 在线"保持；但把"N 路"改成实际的四类
  dbSetAll(function (t) { return /^AI 推理 \d+ 路 · 在线$/.test(t); }, function () { return 'AI 推理 4 类 · 在线'; });
  dbSetAll(function (t) { return t === '数据 200ms 前'; }, function () { return '数据实时'; });
}

