// 视频监控页（v_zc_g4）：把右侧 3 张报警卡填上真数据（最新 3 条报警）。
// 本脚本每秒被平台重跑：状态挂 window，取数节流 10 秒；不在本页（找不到 12 个字段标签）时什么都不做。
var VC_VER = 1;
var _vc = (window.__vcCards = window.__vcCards || {});
if (_vc.ver !== VC_VER) { _vc.ver = VC_VER; _vc.last = 0; _vc.rows = []; }
var VC_FIELDS = ["报警时间：", "报警通道：", "报警类型：", "报警描述："];
var VC_PRIO = { highhigh: "高高限", high: "高", low: "低", lowlow: "低低", message: "提示" };
function vcFmt(t) {
    var d = new Date(t), p = function (n) { return (n < 10 ? "0" : "") + n; };
    return d.getFullYear() + "-" + p(d.getMonth() + 1) + "-" + p(d.getDate()) + " " + p(d.getHours()) + ":" + p(d.getMinutes()) + ":" + p(d.getSeconds());
}
function vcLabels() {
    var ts = document.querySelectorAll("svg text"), out = [];
    for (var i = 0; i < ts.length; i++) {
        var s = (ts[i].textContent || "").trim();
        if (VC_FIELDS.indexOf(s) >= 0) { out.push(ts[i]); }
    }
    return out;   // 本页 12 个（3 卡 × 4 字段）；不在本页为空
}
function vcVal(label, ci, fi, txt) {
    var id = "vc_c" + ci + "_" + fi;
    var el = document.getElementById(id);
    if (!el) {
        el = document.createElementNS("http://www.w3.org/2000/svg", "text");
        el.setAttribute("id", id);
        el.setAttribute("font-family", "微软雅黑");
        el.setAttribute("font-size", "13");
        el.setAttribute("fill", "#dfe9f5");
        el.setAttribute("pointer-events", "none");
        label.parentNode.insertBefore(el, label.nextSibling);
    }
    el.setAttribute("x", String((parseFloat(label.getAttribute("x") || 0) + 92)));
    el.setAttribute("y", label.getAttribute("y") || "0");
    el.textContent = txt;
}
function vcFill() {
    var labels = vcLabels();
    if (labels.length < 12) { return; }
    for (var ci = 0; ci < 3; ci++) {
        var a = _vc.rows[ci];
        var parts = a ? String(a.name || "").split("^~^").filter(Boolean) : [];
        var vals = a ? [
            vcFmt(a.ontime || 0),
            parts[1] || parts[0] || "AI 视频分析",
            VC_PRIO[a.type] || a.type || "视频事件",
            parts.slice(2).join(" · ") || "相机智能事件（区域入侵 / 遮挡 / 移动侦测）"
        ] : ["—", "—", "—", "暂无报警"];
        for (var fi = 0; fi < 4; fi++) { vcVal(labels[ci * 4 + fi], ci, fi, vals[fi]); }
    }
}
function vcTick() {
    var now = Date.now();
    if (now - (_vc.last || 0) < 10000) { vcFill(); return; }
    _vc.last = now;
    // 合并"当前"与"历史"两个口，按时间倒序取最新 3 条
    Promise.all([
        fetch("/api/alarms", { cache: "no-store" }).then(function (r) { return r.ok ? r.json() : []; }).catch(function () { return []; }),
        fetch("/api/alarmsHistory", { cache: "no-store" }).then(function (r) { return r.ok ? r.json() : []; }).catch(function () { return []; })
    ]).then(function (two) {
        var all = (two[0] || []).concat(two[1] || []);
        all.sort(function (a, b) { return (b.ontime || 0) - (a.ontime || 0); });
        _vc.rows = all.slice(0, 3);
        vcFill();
    });
}
vcFill();
vcTick();
